import{c as d,Q as r,j as a,m as e}from"./chunks/framework.rWdQudnF.js";const _=JSON.parse('{"title":"软考-备考-经验贴 2025","description":"","frontmatter":{"title":"软考-备考-经验贴 2025"},"headers":[],"relativePath":"核心速记口诀/经验贴/经验贴 2025.md","filePath":"核心速记口诀/经验贴/经验贴 2025.md","lastUpdated":null}'),p={name:"核心速记口诀/经验贴/经验贴 2025.md"};function l(n,t,o,i,h,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h3 id="报考网站" tabindex="-1">报考网站 <a class="header-anchor" href="#报考网站" aria-label="Permalink to &quot;报考网站&quot;">​</a></h3><p>报考网站</p><p><a href="http://www.ruankao.org.cn" target="_blank" rel="noreferrer">http://www.ruankao.org.cn</a></p><p>51CTO 的在线练习： <a href="https://rk.51cto.com/t/n/chapter-manage/list/sub-240" target="_blank" rel="noreferrer">https://rk.51cto.com/t/n/chapter-manage/list/sub-240</a></p><p>视频教程：主要参考的百度网盘教程中 文老师 的视频</p><p>文档教材：（放到了这里）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20251107232253.png" alt="image.png"></p><p>你的笔记格式的话，建议参考一下别人的，不要孤芳自赏。保持谦虚，持续进步。</p><p>复习建议：</p><ul><li>1、重点是软件工程、架构设计、数据库系统、计算机网络、嵌入式、操作系统、计算机硬件</li></ul><p>考分占比（未更新，之前的分比占比）</p><p>分值最高的几个章节：软件工程、系统架构设计、操作系统知识、数据库系统、计算机网络、面向对象技术</p><table tabindex="0"><thead><tr><th>课题</th><th>分值</th><th>频率</th></tr></thead><tbody><tr><td>计算机硬件</td><td>1</td><td>概率小</td></tr><tr><td>操作系统知识 ☆</td><td>3 - 5</td><td>较为重要</td></tr><tr><td>数据库系统 ☆</td><td>3 -5</td><td>每年</td></tr><tr><td>嵌入式技术</td><td>3 -5</td><td>偶尔</td></tr><tr><td>计算机网络 ☆</td><td>3 -5</td><td>较为重要</td></tr><tr><td>其他计算机系统基础知识</td><td>1</td><td>概率小，了解</td></tr><tr><td>系统配置与性能评价</td><td>1 -2</td><td>偶尔</td></tr><tr><td>信息系统基础知识</td><td>3</td><td>每年</td></tr><tr><td>系统安全</td><td>2 - 4</td><td>每年</td></tr><tr><td>软件工程 ☆</td><td>12 - 15</td><td>每年</td></tr><tr><td>面向对象技术</td><td>3 - 5</td><td>每年</td></tr><tr><td>项目管理</td><td>1</td><td>概率小</td></tr><tr><td>系统架构设计 ☆</td><td>20</td><td>每年</td></tr><tr><td>软件可靠性基础</td><td>2</td><td>偶尔</td></tr><tr><td>未来信息综合技术</td><td>2 -3</td><td>偶尔</td></tr><tr><td></td><td></td><td></td></tr></tbody></table><h3 id="复习建议" tabindex="-1">复习建议 <a class="header-anchor" href="#复习建议" aria-label="Permalink to &quot;复习建议&quot;">​</a></h3><ul><li>整理自己的笔记，需要保持记忆和理解，如果没有理解或者记忆，其实就是忘记了或者不理解。</li><li>案例做适当的题就可以了，论文主要还是看要如何写，一定要尝试自己写，然后改正，这个过程也挺重要的。</li><li>练习题做 老师的课后练习就好。不要纠结，去做，并做好他。</li><li>需要有一个背诵笔记。</li></ul><hr><h3 id="心态记录" tabindex="-1">心态记录 <a class="header-anchor" href="#心态记录" aria-label="Permalink to &quot;心态记录&quot;">​</a></h3><p>2023年下半年考试</p><p>这一年考试，我已经忘记了当时什么感觉了。</p><p>20251108</p><p>这一次，考试之前，我的心态是非常不好的，觉得自己怎么都考不过，实际的考试内容还挺简单的；虽然不知道的结果怎么样，我也没有太沮丧或者开心吧，就是平和，甚至看到考试的时候怀疑自己的准备。但是我觉得你还是应该这么准备，你为什么要打没有准备到仗呢，我更喜欢知识整合的感觉，背诵时候的准备，脑海里充满知识的时候，更喜欢自己的时候。</p><p>软考过了自己又能干嘛呢，我觉得考试更多的是，证明了自己的学习方法论是正确的，知道哪里不足，我不相信运气，我也不想去指望运气。</p><p>我不想纠结其中的细节，考试过程其实还挺平和的，准备的其实挺 一般的，甚至有些不好，但是自己整理东西的方式从这个过程中还是得到了改善，还是希望能多准备了，而且实际上这种应试的学习，包括背诵的内容，建议还是有方法论吧。</p><p>也许面试也是一样的，我们去准备做他，先有自己的方法论，然后去做，直接上就好拉。</p><p>案例的一个准备，可能得换一种方式，这个我也不是很确定哦。</p><p>不知道结果，感觉未知，如果还需要下一次的话，希望自己还是按照自己的感觉去做吧，也不要太纠结了。珍惜过程，期待结果。</p><hr>',27)])])}const u=d(p,[["render",l]]);export{_ as __pageData,u as default};
